def _symbol(value: str) -> str:
    import re

    if re.fullmatch(r"\d{6}", value):
        value += ".SH" if value.startswith(("5", "6", "9")) and not value.startswith("92") else ".BJ" if value.startswith(("4", "8", "92")) else ".SZ"
    return value


def _parameters(source: str, class_name: str) -> list[dict[str, Any]]:
    """Read literal constructor defaults without importing user strategy code."""
    tree = ast.parse(source)
    cls = next((node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == class_name), None)
    if cls is None:
        return []
    init = next((node for node in cls.body if isinstance(node, ast.FunctionDef) and node.name == "__init__"), None)
    if init is None:
        return []
    pairs = list(zip(init.args.args[-len(init.args.defaults):], init.args.defaults)) if init.args.defaults else []
    pairs.extend(zip(init.args.kwonlyargs, init.args.kw_defaults))
    values = []
    for argument, default in pairs:
        if default is None:
            continue
        try:
            value = ast.literal_eval(default)
            json.dumps(value, allow_nan=False)
        except (ValueError, TypeError, SyntaxError):
            continue
        values.append({"name": argument.arg, "value": value, "editable": False})
    return values


def _template_source(parameters: dict[str, int] | None = None) -> tuple[bytes, bytes]:
    original = (_AGENT / "src/skills/multi-factor/example_signal_engine.py").read_bytes()
    tree = ast.parse(original.decode("utf-8"))
    last = tree.body[-1]
    if not (isinstance(last, ast.If) and isinstance(last.test, ast.Compare)
            and isinstance(last.test.left, ast.Name) and last.test.left.id == "__name__"
            and len(last.test.ops) == 1 and isinstance(last.test.ops[0], ast.Eq)
            and len(last.test.comparators) == 1 and isinstance(last.test.comparators[0], ast.Constant)
            and last.test.comparators[0].value == "__main__"):
        raise HTTPException(status_code=503, detail="native strategy example self-test boundary changed")
    executable = b"".join(original.splitlines(keepends=True)[:last.lineno - 1])
    assert ast.dump(ast.parse(executable.decode("utf-8"))) == ast.dump(ast.Module(body=tree.body[:-1], type_ignores=[]))
    if parameters:
        import copy

        expected = copy.deepcopy(ast.parse(executable.decode("utf-8")))
        cls = next(node for node in expected.body if isinstance(node, ast.ClassDef) and node.name == "SignalEngine")
        init = next(node for node in cls.body if isinstance(node, ast.FunctionDef) and node.name == "__init__")
        lines = executable.decode("utf-8").splitlines(keepends=True)
        offsets = [0]
        for line in lines:
            offsets.append(offsets[-1] + len(line))
        replacements = []
        for argument, default in zip(init.args.args[-len(init.args.defaults):], init.args.defaults):
            if argument.arg in parameters:
                replacements.append((offsets[default.lineno - 1] + default.col_offset,
                    offsets[default.end_lineno - 1] + default.end_col_offset, str(parameters[argument.arg])))
                default.value = parameters[argument.arg]
        text = executable.decode("utf-8")
        for start, end, replacement in sorted(replacements, reverse=True):
            text = text[:start] + replacement + text[end:]
        executable = text.encode("utf-8")
        assert ast.dump(ast.parse(text)) == ast.dump(expected), "only native constructor defaults may change"
    return original, executable


def _optimizer_defaults() -> dict[str, dict[str, Any]]:
    result = {}
    base = _parameters((_AGENT / "backtest/optimizers/base.py").read_text(encoding="utf-8"), "BaseOptimizer")
    for name in _OPTIMIZERS:
        source = (_AGENT / "backtest/optimizers" / (name + ".py")).read_text(encoding="utf-8")
        tree = ast.parse(source)
        cls = next(node for node in tree.body if isinstance(node, ast.ClassDef))
        parameters = {item["name"]: item["value"] for item in base + _parameters(source, cls.name)}
        result[name] = parameters
    return result


