    from backtest.engines.china_a import ChinaAEngine
    from backtest.loaders.registry import VALID_SOURCES
    from backtest.runner import BacktestConfigSchema, _VALID_INTERVALS
    from backtest.validation import bootstrap_sharpe_ci, monte_carlo_test, walk_forward_analysis

    today = date.today()
    try:
        start = today.replace(year=today.year - 10)
    except ValueError:
        start = today.replace(year=today.year - 10, day=28)
    schema = BacktestConfigSchema.model_fields
    values = {name: schema[name].default for name in _ALLOWED if name in schema and not schema[name].is_required()}
    engine = ChinaAEngine({})
    values.update(codes=[], start_date=start.isoformat(), end_date=today.isoformat(),
        commission_rate=engine.commission_rate, commission_min=engine.commission_min,
        stamp_tax=engine.stamp_tax, transfer_fee=engine.transfer_fee, slippage=engine.slippage_rate,
        benchmark=None, optimizer=None, optimizer_params={}, validation=None)
    original, executable = _template_source()
    parameters = _parameters(executable.decode("utf-8"), "SignalEngine")
    for parameter in parameters:
        parameter["editable"] = True
    template = {"id": _TEMPLATE, "name": "Vibe 原生多因子示例",
        "description": "原生完整示例：动量、反转、波动率和量比，默认选前三只。它与当前机会选股研究方法不同。",
        "parameters": parameters,
        "source_path": "src/skills/multi-factor/example_signal_engine.py",
        "source_sha256": hashlib.sha256(original).hexdigest(),
        "code_sha256": hashlib.sha256(executable).hexdigest()}
    validation = {}
    for name, function, keys in (
        ("monte_carlo", monte_carlo_test, ("n_simulations", "seed")),
        ("bootstrap", bootstrap_sharpe_ci, ("n_bootstrap", "confidence", "seed")),
        ("walk_forward", walk_forward_analysis, ("n_windows",)),
    ):
        signature = inspect.signature(function)
        validation[name] = {key: signature.parameters[key].default for key in keys}
    fields = {}
    for name, (label, help_text) in _FIELDS.items():
        origin = ("backtest/engines/china_a.py:ChinaAEngine.__init__" if name in {
            "commission_rate", "commission_min", "stamp_tax", "transfer_fee", "slippage"}
            else "src/skills/strategy-generate/SKILL.md:Requirements Parsing" if name in {"start_date", "end_date", "codes"}
            else "backtest/runner.py:BacktestConfigSchema" if name in schema
            else "backtest/engines/base.py:BaseEngine.run_backtest")
        fields[name] = {"label": label, "help": help_text, "default_source": origin}
    return {"defaults": values, "options": {
        "sources": [name for name in ("auto", "tushare", "akshare", "baostock", "tencent", "eastmoney", "gildata", "mootdx", "local") if name in VALID_SOURCES],
        "intervals": [name for name in ("1m", "5m", "15m", "30m", "1H", "4H", "1D", "1W", "1M") if name in _VALID_INTERVALS],
        "position_adjustment": ["hold", "rebalance"], "optimizers": list(_OPTIMIZERS)},
        "fields": fields, "templates": [template], "optimizer_parameters": _optimizer_defaults(),
        "validation_parameters": validation}


def _number(value: Any, name: str, minimum: float = 0, *, positive: bool = False) -> None:
    try:
        finite = math.isfinite(value)
    except (TypeError, OverflowError, ValueError):
        finite = False
    if (isinstance(value, bool) or not isinstance(value, (int, float)) or not finite
            or value < minimum or (positive and value == minimum)):
        raise HTTPException(status_code=422, detail=f"invalid native backtest setting: {name}")


def validate_settings(settings: Any) -> dict[str, Any]:
    from src.api.mona_operations import _valid_iso_date

    if not isinstance(settings, dict) or set(settings) - _ALLOWED:
        raise HTTPException(status_code=422, detail="unsupported native backtest settings")
    try:
        if len(json.dumps(settings, allow_nan=False).encode("utf-8")) > 64 * 1024:
            raise ValueError("settings too large")
    except (ValueError, TypeError, OverflowError) as exc:
        raise HTTPException(status_code=422, detail="backtest settings must be finite JSON") from exc
    clean = json.loads(json.dumps(settings))
    defaults = backtest_defaults()
    for name in ("start_date", "end_date", "evaluation_start_date"):
        if name in clean and not (name == "evaluation_start_date" and clean[name] is None):
            _valid_iso_date(clean[name], name)
    if "codes" in clean:
        import re

        codes = clean["codes"]
        if not isinstance(codes, list) or not 1 <= len(codes) <= 100:
            raise HTTPException(status_code=422, detail="codes must contain 1 to 100 A-share symbols")
        normalized = []
        for code in codes:
            if not isinstance(code, str):
                raise HTTPException(status_code=422, detail="invalid A-share code")
            code = _symbol(code)
            if not re.fullmatch(r"\d{6}\.(SH|SZ|BJ)", code):
                raise HTTPException(status_code=422, detail="codes must be A-share symbols")
            if code not in normalized:
                normalized.append(code)
        clean["codes"] = normalized
    for name in ("source", "interval", "position_adjustment"):
        option = {"source": "sources", "interval": "intervals", "position_adjustment": "position_adjustment"}[name]
        if name in clean and (not isinstance(clean[name], str) or clean[name] not in defaults["options"][option]):
            raise HTTPException(status_code=422, detail=f"unsupported native {name}")
    for name in ("initial_cash", "commission_rate", "commission_min", "stamp_tax", "transfer_fee", "slippage", "rebalance_tolerance"):
        if name in clean:
            _number(clean[name], name, positive=name == "initial_cash")
    if "warmup_bars" in clean and clean["warmup_bars"] is not None and (type(clean["warmup_bars"]) is not int or clean["warmup_bars"] < 0):
        raise HTTPException(status_code=422, detail="warmup_bars must be null or a non-negative integer")
    benchmark = clean.get("benchmark")
    if benchmark is not None:
        import re

        if not isinstance(benchmark, str) or not re.fullmatch(r"\d{6}\.(SH|SZ|BJ)", benchmark):
            raise HTTPException(status_code=422, detail="benchmark must be null or an A-share index symbol")
    if "rebalance_mask" in clean:
        mask = clean["rebalance_mask"]
        if not (mask is None or (isinstance(mask, str) and len(mask) <= 64)
                or (isinstance(mask, list) and len(mask) <= 10000 and all(isinstance(item, str) and len(item) == 10 for item in mask))):
            raise HTTPException(status_code=422, detail="invalid native rebalance_mask")
        from backtest.rebalance_mask import validate_rebalance_mask

        try:
            validate_rebalance_mask(mask)
        except (ValueError, TypeError) as exc:
            raise HTTPException(status_code=422, detail="invalid native rebalance_mask") from exc
    optimizer = clean.get("optimizer")
    if optimizer is not None and (not isinstance(optimizer, str) or optimizer not in _OPTIMIZERS):
        raise HTTPException(status_code=422, detail="unsupported native optimizer")
    parameters = clean.get("optimizer_params", {})
    if not isinstance(parameters, dict):
        raise HTTPException(status_code=422, detail="optimizer_params must be an object")
    # The selected optimizer can be inherited from an existing run. Its exact
    # parameter names are checked after the copy's full config is assembled.
    if set(parameters) - {key for values in defaults["optimizer_parameters"].values() for key in values}:
        raise HTTPException(status_code=422, detail="unsupported native optimizer parameter")
    for name, value in parameters.items():
        if name == "lookback":
            if type(value) is not int or value < 1:
                raise HTTPException(status_code=422, detail="optimizer lookback must be a positive integer")
        elif name in {"groups", "max_per_group"}:
            if value is None:
                continue
            if not isinstance(value, dict) or len(value) > 100 or any(not isinstance(key, str) or len(key) > 64 for key in value):
                raise HTTPException(status_code=422, detail=f"invalid optimizer {name}")
            for item in value.values():
                if name == "groups":
                    if not isinstance(item, str) or len(item) > 64:
                        raise HTTPException(status_code=422, detail="optimizer groups must be text mappings")
                else:
                    _number(item, name, positive=True)
                    if item > 1:
                        raise HTTPException(status_code=422, detail="group weight caps must be at most 1")
            if name == "groups":
                normalized = {_symbol(key): item for key, item in value.items()}
                if len(normalized) != len(value):
                    raise HTTPException(status_code=422, detail="optimizer groups contain duplicate stock codes")
                parameters[name] = normalized
        elif name == "max_per_name" and value is None:
            continue
        else:
            _number(value, name, minimum=-1e100 if name == "risk_free" else 0)
            if name == "max_per_name" and not 0 < value <= 1:
                raise HTTPException(status_code=422, detail="per-name weight cap must be in (0,1]")
    validation = clean.get("validation")
    if validation is not None:
        allowed = defaults["validation_parameters"]
        if not isinstance(validation, dict) or set(validation) - set(allowed):
            raise HTTPException(status_code=422, detail="unsupported native validation")
        for name, params in validation.items():
            if not isinstance(params, dict) or set(params) - set(allowed[name]):
                raise HTTPException(status_code=422, detail="unsupported native validation parameter")
            for key, value in params.items():
                if key == "confidence":
                    _number(value, key, positive=True)
                    if value >= 1:
                        raise HTTPException(status_code=422, detail="confidence must be between 0 and 1")
                elif type(value) is not int or value < (0 if key == "seed" else 1):
                    raise HTTPException(status_code=422, detail=f"invalid native validation {key}")
    return clean


def _effective(config: dict[str, Any]) -> dict[str, Any]:
    from backtest.runner import BacktestConfigSchema

    values = {**backtest_defaults()["defaults"], **{key: value for key, value in config.items() if key in _ALLOWED}}
    clean = validate_settings(values)
    if config.get("engine", "daily") != "daily":
        raise HTTPException(status_code=422, detail="this configuration surface supports native daily engines")
    optimizer = clean.get("optimizer")
    params = clean.get("optimizer_params", {})
    if params and (optimizer is None or set(params) - set(_optimizer_defaults()[optimizer])):
        raise HTTPException(status_code=422, detail="parameters do not belong to the selected optimizer")
    if optimizer == "turnover_aware" and set(params.get("max_per_group") or {}) - set((params.get("groups") or {}).values()):
        raise HTTPException(status_code=422, detail="group caps require matching stock-to-group mappings")
    if clean.get("warmup_bars") not in (None, 0) and clean.get("evaluation_start_date") is not None:
        raise HTTPException(status_code=422, detail="declare warmup_bars or evaluation_start_date, not both")
    if clean.get("evaluation_start_date") is not None and not clean["start_date"] <= clean["evaluation_start_date"] <= clean["end_date"]:
        raise HTTPException(status_code=422, detail="evaluation_start_date must be inside the data window")
    try:
        BacktestConfigSchema.model_validate({**config, **clean})
    except ValueError as exc:
        raise HTTPException(status_code=422, detail="settings do not satisfy the native backtest config") from exc
    return {**clean, "engine": "daily"}


def _read_config(run_dir: Path) -> dict[str, Any]:
    from src.api.mona_operations import _contains_credentials, _is_link, _read_bounded

    path = run_dir / "config.json"
    if _is_link(path) or not path.is_file() or path.resolve().parent != run_dir.resolve():
        raise HTTPException(status_code=422, detail="native input config is unavailable")
    try:
        value = json.loads(_read_bounded(path, 1024 * 1024, "input config"))
    except (ValueError, UnicodeError) as exc:
        raise HTTPException(status_code=422, detail="native input config is invalid") from exc
    if not isinstance(value, dict) or _contains_credentials(value):
        raise HTTPException(status_code=422, detail="native input config must not contain credentials")
    return value


def validate_backtest(payload: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    from src.api.mona_operations import _resolve_run, _run_code_sha256

    if bool("run_id" in payload) == bool("template_id" in payload):
        raise HTTPException(status_code=422, detail="select exactly one native input run or template")
    settings = validate_settings(payload.get("settings", {}))
    clean = {"operation": "backtest", "settings": settings, "_configure_settings": "settings" in payload}
    if "template_id" in payload:
        if payload["template_id"] != _TEMPLATE:
            raise HTTPException(status_code=422, detail="unsupported native strategy template")
        _effective({**backtest_defaults()["defaults"], **settings})
        clean["template_id"] = _TEMPLATE
        clean["_configure_settings"] = True
        parameters = payload.get("strategy_parameters", {})
        allowed = {item["name"] for item in backtest_defaults()["templates"][0]["parameters"]}
        if (not isinstance(parameters, dict) or set(parameters) - allowed
                or any(type(value) is not int or value < 1 for value in parameters.values())):
            raise HTTPException(status_code=422, detail="native example parameters must be known positive integers")
        clean["strategy_parameters"] = parameters
        return clean, {"template_id": _TEMPLATE}
    if "strategy_parameters" in payload:
        raise HTTPException(status_code=422, detail="existing run strategy parameters are read-only")
    run_dir = _resolve_run(payload["run_id"])
    config = _read_config(run_dir)
    if clean["_configure_settings"]:
        _effective({**config, **settings})
    _run_code_sha256(run_dir)
    clean.update(input_run_id=payload["run_id"], _input_run_dir=str(run_dir))
    return clean, {"input_run_id": payload["run_id"]}


def configured_run(payload: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    from src.api.mona_operations import _copy_versioned_run, _is_link, _remove_versioned_run, _run_code_sha256
