    source_meta = {}
    if template_id:
        import uuid

        runs_path = get_runs_dir()
        if _is_link(runs_path):
            raise HTTPException(status_code=422, detail="native runs directory may not be a link")
        runs_path.mkdir(parents=True, exist_ok=True)
        root = runs_path.resolve(strict=True)
        if root != get_runtime_root().resolve(strict=True) / "runs":
            raise HTTPException(status_code=422, detail="native runs directory escapes private state")
        run_id = "mona-" + uuid.uuid4().hex
        run_dir = root / run_id
        run_dir.mkdir()
        try:
            original, executable = _template_source(payload.get("strategy_parameters"))
            (run_dir / "code").mkdir()
            (run_dir / "code/signal_engine.py").write_bytes(executable)
            config = backtest_defaults()["defaults"]
            source_meta = {"template_id": template_id,
                "template_source": "src/skills/multi-factor/example_signal_engine.py",
                "template_source_sha256": hashlib.sha256(original).hexdigest(),
                "template_executable_sha256": hashlib.sha256(executable).hexdigest(),
                "self_test_removed_only": not bool(payload.get("strategy_parameters")),
                "constructor_defaults_only_changed": bool(payload.get("strategy_parameters")),
                "strategy_parameters": {item["name"]: item["value"] for item in _parameters(executable.decode("utf-8"), "SignalEngine")}}
        except Exception:
            _remove_versioned_run(run_id, run_dir)
            raise
    else:
        run_id, run_dir = _copy_versioned_run(payload["input_run_id"], Path(payload["_input_run_dir"]))
        config = _read_config(run_dir)
        source_meta = {"input_run_id": payload["input_run_id"]}
    try:
        if payload.get("_configure_settings"):
            effective = _effective({**config, **payload.get("settings", {})})
            final_config = {**config, **effective}
            config_bytes = (json.dumps(final_config, ensure_ascii=False, indent=2, allow_nan=False) + "\n").encode("utf-8")
            (run_dir / "config.json").write_bytes(config_bytes)
        else:
            # Preserve the old generic Backtest(run_id) contract byte-for-byte.
            config_bytes = (run_dir / "config.json").read_bytes()
            try:
                effective = _effective(config)
            except HTTPException:
                effective = {key: value for key, value in config.items() if key in _ALLOWED or key == "engine"}
        references = {**source_meta, "run_id": run_id, "settings": payload.get("settings", {}),
            "effective_config": effective, "config_sha256": hashlib.sha256(config_bytes).hexdigest(),
            "code_sha256": _run_code_sha256(run_dir)}
        (run_dir / "mona_backtest_settings.json").write_text(json.dumps(references, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        worker = {"operation": "backtest", "run_id": run_id, "_run_dir": str(run_dir)}
        persisted = {"operation": "backtest", **references}
        return worker, persisted, references
    except Exception:
        _remove_versioned_run(run_id, run_dir)
        raise


def backtest_inputs(limit: int = 100) -> dict[str, Any]:
    from src.api.mona_operations import _is_link, _read_bounded, _resolve_run, _run_code_sha256
    from src.api.mona_reads import _backtest_run_status
    from src.config.paths import get_runs_dir, get_runtime_root

    root = get_runs_dir()
    if not root.is_dir() or _is_link(root):
        return {"inputs": []}
    entries = []
    for path in list(root.iterdir())[:1000]:
        try:
            if not _is_link(path) and path.is_dir():
                entries.append((path.stat().st_mtime_ns, path))
        except OSError:
            continue
    entries.sort(key=lambda item: item[0], reverse=True)
    inputs = []
    for _modified_ns, path in entries:
        try:
            run_dir = _resolve_run(path.name)
            config = _read_config(run_dir)
            effective = _effective(config)
            code_sha = _run_code_sha256(run_dir)
            signal_file = run_dir / "code/signal_engine.py"
            code = _read_bounded(signal_file, 1024 * 1024, "strategy code").decode("utf-8")
            inputs.append({"run_id": path.name, "title": path.name,
                "status": _backtest_run_status(run_dir, get_runtime_root().resolve()),
                "config": {key: value for key, value in config.items() if key in _ALLOWED or key == "engine"},
                "effective_config": effective, "strategy_parameters": _parameters(code, "SignalEngine"),
                "config_sha256": hashlib.sha256((run_dir / "config.json").read_bytes()).hexdigest(),
                "code_sha256": code_sha})
        except (HTTPException, OSError, ValueError, SyntaxError, UnicodeError):
            continue
        if len(inputs) >= limit:
            break
    return {"inputs": inputs}
